update public.products set description='Turkey mid-wings are the middle sections of turkey wings, offering bone-in meat and skin in convenient portions for grilling, frying, roasting, stews and other seasoned dishes.', handling_protocols=array['Keep raw portions cold and separated from ready-to-eat foods.','Do not wash raw turkey; clean hands, utensils and surfaces after handling.','Cook the thickest part to at least 74°C / 165°F without measuring directly against the bone.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','If frozen, keep at about -18°C or below and use within about 6–9 months for best quality.']::text[] where name='Turkey Mid-Wings' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Turkey laps are large, meaty bone-in turkey leg portions suited to roasting, grilling, frying, peppered dishes, soups and stews.', handling_protocols=array['Keep raw turkey laps cold and isolated from ready-to-eat foods.','Do not wash raw turkey; clean hands, utensils and surfaces after handling.','Cook the thickest part to at least 74°C / 165°F without measuring directly against the bone.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','If frozen, keep at about -18°C or below and use within about 6–9 months for best quality.']::text[] where name='Turkey Laps' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
